// fullUsage mirrors TypeScript's top-level CLI help. The subprocess parity
// matrix verifies it byte-for-byte against src/cli/index.ts.
package ocxcli

const (
	startHelp    = "Usage: ocx start [--port <port>]\n\nStart the proxy server and sync models to Codex.\n"
	stopHelp     = "Usage: ocx stop\n\nStop the proxy and restore native Codex config.\n"
	v2Help       = "Usage: ocx v2 <status|on|off|mode <v1|default|v2>|keep-native-v1 <on|off>|threads <n>>\n\nToggle the Codex multi_agent_v2 feature (multi-agent surface).\n\nstatus                Show flag, multi-agent mode, and thread limit.\non | off              Enable/disable multi_agent_v2 (catalog resyncs).\nmode <v1|default|v2>  Force all models to one surface, or respect upstream pins.\nkeep-native-v1 <on|off>  Under mode v2, keep ChatGPT-native models on v1.\nthreads <n>           Set max_concurrent_threads_per_session (integer >= 1).\nFlips preserve the active thread limit while moving between v1/v2 modes.\n"
	providerHelp = "Usage: ocx provider <list|add|edit|test|remove|show|set-default|selected|quota|presets|account-mode>\n\nNon-interactive provider management.\n\nSubcommands: list, add/edit/test/remove/show, set-default, selected, quota, presets, account-mode\nRegistry providers are auto-configured by name. Custom providers need --adapter and --base-url.\nRun `ocx provider --help` for full usage and examples.\n"
	claudeHelp   = "Usage: ocx claude [claude args...]\n\nLaunch Claude Code wired to the proxy (env injection + gateway model discovery).\n\nEnsures the proxy is running, then execs `claude` with ANTHROPIC_BASE_URL/ANTHROPIC_AUTH_TOKEN,\nCLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY=1 and model slots from config.claudeCode.\nRouted models appear in the native /model picker with stable claude-opus-4-8-2026MMDD slot aliases (Claude Code >= 2.1.129).\nOlder versions: pick models via ANTHROPIC_MODEL or /model <id> directly (any string passes through).\nUser-exported ANTHROPIC_* variables always take precedence.\n\nClaude Desktop profile:\n  ocx claude desktop [apply]                         Save and apply the four-family profile\n  ocx claude desktop show [--json]                   Show routes, families, and defaults\n  ocx claude desktop status [--json]                 Show applied state, drift, and health\n  ocx claude desktop move <route> <family> [--default]\n  ocx claude desktop default <family> <route|none>\n  ocx claude desktop export <path|->                 Export versioned JSON (`-` = stdout)\n  ocx claude desktop import <path> [--apply]         Validate and import JSON\nFamilies: opus, fable, sonnet, haiku. New routes start in opus.\n`none` is valid only when that family is empty.\nLegacy apply flags remain supported: --static, --hybrid, --discovery-only.\n\nClaude Code settings: ocx claude config <status|set> ...\n"
	opencodeHelp = "Usage: ocx opencode [opencode args...]\n\nLaunch opencode wired to the proxy (runtime provider config).\n\nEnsures the proxy is running, then execs `opencode` with the generated `provider.opencodex`\nand `providers.opencodex` blocks injected through OpenCode's inline runtime layer\n(`OPENCODE_CONFIG_CONTENT`). Any existing inline config in the environment is preserved\nand only `provider.opencodex` and `providers.opencodex` are overwritten for this launch.\nOnly the V2 block (`providers.opencodex`) carries the reasoning-effort variants.\nGlobal/project opencode.json may be read to warn about an existing provider.opencodex or\nproviders.opencodex override; on-disk files are never modified.\nRouted models appear in the model picker as opencodex/<provider>/<model>.\nStop using `ocx opencode` and plain `opencode` behaves exactly as before.\n"
)

const fullUsage = "opencodex (ocx) — Universal provider proxy for Codex\n\nUsage:\n  ocx setup                   Interactive setup (alias: init)\n  ocx start [--port <port>]   Start the proxy server (auto-syncs models to Codex)\n  ocx stop                    Stop the proxy AND restore native Codex (plain codex works again)\n  ocx restore                 Restore native Codex without stopping (alias: eject)\n  ocx restore back            Re-point codex at the running proxy (undo restore)\n  ocx recover-history --legacy-openai --yes\n                               Force all user-message opencodex rows to OpenAI (legacy recovery)\n  ocx uninstall               Remove service/shim/config and restore native Codex (alias: remove)\n  ocx service [sub]           Run as a background service (default: install/update/start)\n  ocx codex-shim <sub>        Auto-start proxy when `codex` launches (install|status|uninstall|remove)\n  ocx tray <sub>              Windows status tray (install|start|stop|status|uninstall)\n  ocx ensure                  Ensure the proxy is running and Codex config/cache are current\n  ocx connect <url>           Connect this machine to a remote OpenCodex hub (credential via stdin)\n  ocx disconnect              Restore local state and clear the hub connection\n  ocx sync [--restart-codex]  Fetch models from providers and inject into Codex config\n  ocx sync-cache [--restart-codex]\n                              Refresh Codex's model cache from the active catalog\n  ocx status                  Check proxy server status\n  ocx doctor                  Diagnose environment/network issues (WSL, proxy, ChatGPT reachability)\n  ocx doctor --reclaim-response-temps\n                              Reclaim abandoned response-state temp files (works without a running proxy)\n  ocx doctor --recover-zero-byte-coordinator --yes\n                              Back up a proven zero-byte Codex coordinator after stopping the proxy\n  ocx debug <scope>           provider/usage/injection/claude on|off|status|reset\n  ocx login <provider>        OAuth or API-key provider login\n  ocx logout <provider>       Remove a stored OAuth login\n  ocx gui [pair --origin <browser-origin> [--json]]\n                              Open the dashboard or create a single-use remote pairing grant\n  ocx update [--tag <tag>]    Update opencodex (keeps preview installs on @preview)\n  ocx restart                  Stop and restart the proxy\n  ocx v2 <sub>                multi_agent_v2 surface (status|on|off|mode|keep-native-v1|threads|mode-hint)\n  ocx health [--json]          Check proxy health (exit 0=healthy, 1=not)\n  ocx capabilities [--json]    List declared capabilities and the API routes they drive\n  ocx ready [--json] [--wait [--timeout <s>]]  Check post-sync readiness (exit 0 only when ready)\n  ocx provider <sub>          Providers, connectivity, quota, and selected models\n  ocx account <sub>           Accounts, login/reauth, key pools, and quota controls\n  ocx models <sub>            Live/custom models, visibility, context, and shadow calls\n  ocx alias <sub>             Short names for providers and models (list, set, rm, defaults)\n  ocx combo <sub>             Combo routing strategies and failover\n  ocx agent <sub>             Subagents, injection, effort caps, and sidecars\n  ocx observe <sub>           Logs, usage, storage, memory, and debug data\n  ocx inspect <sub>           Effective config, catalog, analytics, pacing, client-config\n  ocx route <sub>             Routing features (combo, policy)\n  ocx logs [filters]          Alias of ocx observe logs\n  ocx usage [--range <today|1d|7d|30d|all>] [--provider <name>] [--model <id>]\n                              Token and estimated-cost report (alias of ocx observe usage)\n  ocx storage <sub>           Storage report, cleanup, trash, and the cleanup policy\n  ocx memory [--json]         Alias of ocx observe memory\n  ocx api-key <sub>           Alias of ocx access key\n  ocx access <sub>            External API keys and endpoint information\n  ocx export --client <id>    Print a client config wired to the running proxy (12 clients)\n  ocx integration client <sub> Enable, disable, inspect or roll back a client integration\n  ocx grok <sub>              Grok Build model selection and apply\n  ocx system <sub>            Runtime settings, startup, sync, OpenCodex updates, and Codex CLI inspection\n  ocx config <sub>            Validated configuration show/get/set/import/export\n  ocx lab <sub>               Read-only Compatibility Lab projection inspection\n  ocx claude [args...]        Launch Claude Code wired to the proxy (model discovery on)\n  ocx claude desktop [sub]    Manage and apply Claude Desktop's four-family profile\n  ocx opencode [args...]      Launch opencode wired to the proxy (runtime provider config)\n  ocx mcode [args...]         Launch MiniMax Code through its managed provider\n  ocx mmx text <sub> [args]   Launch MiniMax CLI text through the proxy\n  ocx zcode [sub]             Connect ZCode to the proxy (managed provider)\n  ocx help [command]          Show help\n  ocx --version | -v          Print version\n\nExamples:\n  ocx init                    Set up provider and inject into Codex\n  ocx start                   Start on default port (10100)\n  ocx start --port 8080       Start on custom port\n  ocx help service            Show service command help\n  ocx sync                    Sync available models to Codex\n"

